import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../../data/repositories/quran_repository.dart';import '../../data/models/surah.dart';import 'surah_page.dart';
class SurahListPage extends StatelessWidget{const SurahListPage({super.key});@override Widget build(BuildContext c){return SafeArea(child:FutureBuilder<List<Surah>>(future:c.read<QuranRepository>().surahs(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final x=s.data!;return CustomScrollView(slivers:[SliverAppBar(title:const Text('Qur’an'),floating:true,actions:[IconButton(onPressed:(){},icon:const Icon(Icons.search))]),SliverList.builder(itemCount:x.length,itemBuilder:(c,i){final a=x[i];return ListTile(leading:CircleAvatar(child:Text('${a.id}')),title:Text(a.nameEn),subtitle:Text('${a.translit} • ${a.ayahCount} ayahs'),trailing:Text(a.nameAr,style:const TextStyle(fontSize:20)),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>SurahPage(surah:a))));})]);}));}}
